"""Record connected completion-join/controller evidence without full-system claims."""
from pathlib import Path
import datetime,hashlib,json,zipfile
ROOT=Path(__file__).resolve().parents[1];BASE=ROOT/'artifacts/analog_asic'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def rel(p):return p.relative_to(ROOT).as_posix()
def main():
 cell='gf180_joined_bin_controller_v2';folder=BASE/'layout'/cell;source=ROOT/'scripts/screen_gf180_joined_bin_controller_nominal.py';rp=BASE/'results'/f'{cell}_case1_src{sha(source)[:12]}.json';r=json.loads(rp.read_text());assert r['module_simulation_completed'] and r['join_connected_pass']
 old=BASE/'assembly/article_module_catalog_v11.json';cp=BASE/'assembly/article_module_catalog_v12.json';assert not cp.exists();cat=json.loads(old.read_text());assert all(sha(ROOT/n)==h for n,h in cat['sha256'].items())
 qs=[folder/n for n in ['qualification.json','flat_cap_qualification.json','abstract_qualification.json']];q,fq,aq=[json.loads(p.read_text()) for p in qs];assert q['magic_drc_count']==0 and q['lvs_unique'] and q['gds_roundtrip_lvs_unique'] and q['gds_roundtrip_drc_count']==0 and fq['flat_lvs_unique'] and not fq['negative_aggregate_branches'] and aq['physical_ports_and_size_verified']
 for d in [r,fq,aq]:
  for n,h in d['sha256'].items():
   if Path(n).suffix!='.ext':assert sha(ROOT/n)==h,n
 files=[*qs,rp,folder/(cell+'.gds'),folder/(cell+'.lef'),folder/(fq['flat_subcircuit']+'_cap.spice')]
 entry={'cell':cell,'role':'connected_bin_completion_and_commit_control','dense_resident_leaf':False,'complete_neuron_functionally_accepted':False,'mos_count':398,'native_mim_count':0,'ports':q['ports'],'bbox_um':q['bbox_um'],'module_layout_and_nominal_simulation_artifacts_complete':True,'join_connected_nominal_pass':True,'views':{p.name:rel(p) for p in files},'limitations':r['scope']+' Spacious characterization parent, not dense storage geometry.'};cat['characterization_assemblies'].append(entry);cat['revision']=12;cat['previous_catalog']=rel(old);cat['sha256'].update({rel(p):sha(p) for p in files});cat['next_physical_modules']=['graph_wide_barrier_and_queue_drain','shared_bias_references','analog_RMS_adaptation_inhibition_final_readout','dense_resident_and_weight_cells'];cat['next_assembly']='Remaining analog support functions, dense tile and full executed25actor hierarchy; global barrier/control and analog operation completion still need integration.';cp.write_text(json.dumps(cat,indent=2)+'\n')
 bp=BASE/'results/gf180_joined_bin_control_article_boundary.json';assert not bp.exists();audit={'catalog':rel(cp),'modules':14,'characterization_assemblies':9,'joined_control_nominal_pass':True,'cases':r['cases'],'join_complete_rising_edges_s':r['join_complete_rising_edges_s'],'limitations':entry['limitations'],'full_chip_layout_complete':False,'original_float_accuracy_accepted':False,'full_5ms_population_service_accepted':False,'sha256':{rel(p):sha(p) for p in [cp,*files,Path(__file__)]}};bp.write_text(json.dumps(audit,indent=2)+'\n')
 docs=[ROOT/'docs'/n for n in ['AGENTS.md','ACTIVE_TASKS.md','ARCHITECTURE.md','DECISIONS.md','RESULTS.md','PROGRESS.md','project_spec.yaml']];stamp=datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%SZ');zp=BASE/'documentation_history'/('project_docs_before_joined_bin_control_'+stamp+'.zip')
 with zipfile.ZipFile(zp,'x',zipfile.ZIP_DEFLATED) as z:
  for p in docs:z.writestr(rel(p),p.read_bytes())
 zp.with_suffix('.json').write_text(json.dumps({'archive_sha256':sha(zp),'files':{rel(p):{'bytes':p.stat().st_size,'sha256':sha(p)} for p in docs}},indent=2)+'\n')
 def write(p,b):
  tmp=p.with_suffix('.tmp');tmp.write_bytes(b);tmp.replace(p)
 def insert(name,text):
  p=ROOT/'docs'/name;b=p.read_bytes();i=b.index(b'\n## ');write(p,b[:i]+text.encode('utf-8')+b[i:])
 insert('RESULTS.md',f'\n## Connected bin completion and commit control - 2026-10-10\n\n[Connected boundary](../{rel(bp)}) records real398MOS join/controller parent revision2, full DRC0/LVS and GDS reimport, actual LEF and2008 nonnegative flat capacitance branches. Two branch tokens drive the physical sticky join; no external COMPLETE source. Nominal waiting/phase-order/commit check passes and DETECT follows joined COMPLETE. Catalog revision12:14 reusable module sets and9 characterization assemblies. Revision1 failed at exported Metal5 pin islands; revision2 extends global routes to cover pins, preserving failed evidence.\n\nOnly one active semantic bin and external valid tokens; graph-wide barrier, queue draining and connected analog phase completion remain unfinished. Not complete PLIF, model accuracy or population5ms acceptance.\n')
 insert('ARCHITECTURE.md','\n## Connected bin-control boundary - 2026-10-10\n\nPhysical two-branch join drives bin-controller COMPLETE. Separate JOIN_CLEAR/RESET are tied only in the nominal fixture; global epoch clear must span capture after all old tokens/events drain. Analog model state persists across clearing control flags. No encoded tags or overlapping bins. Control outputs name operations; actual beta/threshold/RMS/reset/adaptation completion is not proved by a strobe alone.\n')
 insert('PROGRESS.md',f'\nConnected bin-control milestone: native398MOS parent, physical and nominal extracted check complete;14 reusable module sets/9 characterization assemblies, catalog revision12. Exact prior docs: `{rel(zp)}`. Next remaining analog support, global barrier and dense/full assembly; overall goal incomplete.\n')
 p=ROOT/'docs/ACTIVE_TASKS.md';b=p.read_bytes().replace(b'article_module_catalog_v11.json',b'article_module_catalog_v12.json').replace(b'catalog revision11',b'catalog revision12').replace(b'and8 routed',b'and 9 routed').replace(b'and8 characterization',b'and 9 characterization').replace(b'and8 assemblies',b'and 9 assemblies').replace(b'contains14 completed',b'contains 14 completed');a=b.index(b'| Job status |');z=b.index(b'\n',a);b=b[:a]+b'| Job status | Bin controller and join each pass three cases; connected398MOS parent physical and nominal checks complete; next analog support and dense/full assembly |'+b[z:];write(p,b)
 p=ROOT/'docs/project_spec.yaml';b=p.read_bytes();head,tail=b.split(b'\ndocument:',1);head=head.replace(b'article_module_catalog_v11.json',b'article_module_catalog_v12.json').replace(b'gf180_bin_completion_join2_v1_article_boundary.json',bp.name.encode()).replace(b'artifacts/analog_asic/results/'+bp.name.encode(),rel(bp).encode()).replace(b'  live_sessions: [joined_bin_controller_nominal_bounded_360s]',b'  live_sessions: []').replace(b'14_modules_8_assemblies_latest_control_cases_complete',b'14_modules_9_assemblies_connected_bin_control_nominal_complete');write(p,head+b'\ndocument:'+tail)
 print(json.dumps({'catalog':rel(cp),'boundary':rel(bp),'modules':14,'assemblies':9},indent=2))
if __name__=='__main__':main()
